<script setup lang="ts">
import{reactive,ref,watch}from'vue'
import{useRouter}from'vue-router';import{state}from'../store';import{api,run,resetCsrf}from'../api'
import type{Row}from'../types'
import{joinTypes,clubDivisions,memberStatusName}from'../membership'
const router=useRouter();
const props=defineProps<{member:Row}>(),emit=defineEmits<{close:[],saved:[]}>(),formRef=ref(),busy=ref(false)
const form=reactive({name:props.member.name,email:props.member.email,studentNo:props.member.studentNo,department:props.member.department,contact:props.member.contact||'',grade:props.member.grade||'',joinType:props.member.memberType||props.member.joinType||'UNASSIGNED',clubDivision:props.member.clubDivision||'',memberStatus:props.member.memberStatus||'NONE',note:props.member.memberNote||''})
const account=reactive({username:props.member.username,bio:props.member.bio||'',newPassword:''});
const rules={name:[{required:true,message:'请填写姓名',trigger:'blur'}],email:[{required:true,type:'email',message:'请填写有效邮箱',trigger:'blur'}],studentNo:[{required:true,message:'请填写学号',trigger:'blur'}],department:[{required:true,message:'请填写学院',trigger:'blur'}]}
watch(()=>form.joinType,v=>{if(v!=='CLUB')form.clubDivision=''})
async function save(){if(!await formRef.value?.validate().catch(()=>false))return;busy.value=true;await run(async()=>{await api('/admin/users/'+props.member.id+'/profile','PUT',form);if(state.user?.role==='SUPER_ADMIN'){await api('/admin/users/'+props.member.id+'/account','PUT',account);if(state.user.id===props.member.id&&(account.username!==props.member.username||account.newPassword)){state.user=null;resetCsrf();emit('close');router.replace('/login');return}}emit('saved')},'成员资料已保存，身份权限已同步');busy.value=false}
</script>
<template><el-dialog :model-value="true" @update:model-value="(v:boolean)=>{if(!v)emit('close')}" title="编辑成员资料" width="min(680px, 94vw)" :close-on-click-modal="false"><p class="muted small">账号：{{member.username}}。成员身份与管理员权限分开管理，超级管理员可重置密码，用户名或密码变更后该账号须重新登录。</p><el-form ref="formRef" :model="form" :rules="rules" label-position="top" @submit.prevent="save"><template v-if="state.user?.role==='SUPER_ADMIN'"><el-form-item label="用户名"><el-input v-model="account.username" maxlength="32"/></el-form-item><el-form-item label="个人简介"><el-input v-model="account.bio" type="textarea" maxlength="500"/></el-form-item><el-form-item label="重置密码（不填则保留）"><el-input v-model="account.newPassword" type="password" autocomplete="new-password" maxlength="64"/></el-form-item></template><div class="form-grid"><el-form-item label="姓名" prop="name"><el-input v-model="form.name" maxlength="50"/></el-form-item><el-form-item label="学号" prop="studentNo"><el-input v-model="form.studentNo" maxlength="30"/></el-form-item></div><el-form-item label="邮箱" prop="email"><el-input v-model="form.email" type="email" maxlength="120"/></el-form-item><div class="form-grid"><el-form-item label="所在学院" prop="department"><el-input v-model="form.department" maxlength="100"/></el-form-item><el-form-item label="所在年级"><el-input v-model="form.grade" maxlength="40"/></el-form-item></div><el-form-item label="联系方式"><el-input v-model="form.contact" maxlength="120"/></el-form-item><div class="form-grid"><el-form-item label="加入类型"><select v-model="form.joinType" class="native-select" aria-label="成员加入类型"><option value="UNASSIGNED">待分类</option><option v-for="t in joinTypes" :key="t.value" :value="t.value">{{t.label}}</option></select></el-form-item><el-form-item label="成员状态"><select v-model="form.memberStatus" class="native-select" aria-label="成员审核状态"><option v-if="member.memberStatus==='NONE'" value="NONE">未申请</option><option v-for="s in ['PENDING','APPROVED','REJECTED','WITHDRAWN']" :key="s" :value="s">{{memberStatusName(s)}}</option></select></el-form-item></div><el-form-item v-if="form.joinType==='CLUB'" label="俱乐部部门"><select v-model="form.clubDivision" class="native-select" aria-label="俱乐部部门"><option value="">暂未分配</option><option v-for="d in clubDivisions" :key="d" :value="d">{{d}}</option></select></el-form-item><div class="info-box">审核通过前请确认加入类型。成员身份与场地权限按保存后的类别和状态生效；器材申请沿用原有审核流程，已有借还与活动记录保留。</div><el-form-item label="审核 / 调整说明"><el-input v-model="form.note" type="textarea" :rows="3" maxlength="500" show-word-limit/></el-form-item></el-form><template #footer><el-button @click="emit('close')">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存成员资料</el-button></template></el-dialog></template>
